jsonTools.init:
function init(eli) {
  if (!eli.events) eli.events = { guard: function (fn) { return fn; }, safeAsync: function (p) { return p; } };

  // ─── Audience gate ────────────────────────────────────────────────
  // Defensive in-tool check; the tool_configs audienceEmails gate is
  // the primary filter but this prevents accidental wide-load damage.
  var ALLOWED = { "andrew_nemiroff@colpal.com": 1 };
  var ident = (eli.tools && typeof eli.tools.userIdentity === "function")
    ? eli.tools.userIdentity() : {};
  var userEmail = String((ident && ident.email) || "").toLowerCase().trim();
  if (!ALLOWED[userEmail]) {
    eli.log.event("tool", "eli_agent_skip", { reason: "not_allowed", email: userEmail });
    return;
  }

  // ─── Agent registry ───────────────────────────────────────────────
  // V1 ships with one agent (apply_instruction → "Revise Document").
  // Adding agent #2 = push another entry; the dropdown + Manage Agents
  // modal are data-driven off this list. displayName is what the user
  // sees; id is what flows through dispatch payloads + IDB keys.
  var AGENT_REGISTRY = [
    {
      id: "apply_instruction",
      displayName: "Revise Document",
      icon: "🤖",
      description: "Make multiple edits across the doc based on a free-form instruction (e.g., \"Make this Colgate-friendly\", \"Shorten by 30%\").",
      defaultSettings: {
        tone: "balanced",  // conservative | balanced | aggressive
        scope: ["payment-terms", "indemnity", "termination", "ip", "mfn", "audit", "warranty"],
      },
    },
  ];

  // ─── Per-user agent settings (IDB) ────────────────────────────────
  // One row per agent id under config store. Settings ride on the
  // agent_settings shape: { enabled, tone, scope }. Defaults derive
  // from the registry's defaultSettings until the user overrides.
  var SETTINGS_KEY_PREFIX = "eli_agent_settings_";
  function _settingsKey(agentId) { return SETTINGS_KEY_PREFIX + agentId; }
  function _getAgentSettings(agentId) {
    var entry = _findAgent(agentId);
    if (!entry) return Promise.resolve(null);
    return eli.storage.get("config", _settingsKey(agentId)).then(function (row) {
      var saved = (row && row.settings) || {};
      return Object.assign(
        { enabled: true },
        entry.defaultSettings || {},
        saved
      );
    }).catch(function () {
      return Object.assign({ enabled: true }, entry.defaultSettings || {});
    });
  }
  function _setAgentSettings(agentId, settings) {
    if (!_findAgent(agentId)) return Promise.reject(new Error("Unknown agent id: " + agentId));
    return eli.storage.put("config", {
      key: _settingsKey(agentId),
      agentId: agentId,
      settings: settings || {},
      updatedAt: new Date().toISOString(),
    });
  }
  function _findAgent(id) {
    for (var i = 0; i < AGENT_REGISTRY.length; i++) {
      if (AGENT_REGISTRY[i].id === id) return AGENT_REGISTRY[i];
    }
    return null;
  }
  // Returns the public registry projection — what callers see via
  // list_agents dispatch. Strips internal fields, joins persisted
  // enable state per row. Async because settings live in IDB.
  function _listAgents() {
    return Promise.all(AGENT_REGISTRY.map(function (a) {
      return _getAgentSettings(a.id).then(function (s) {
        return {
          id: a.id,
          displayName: a.displayName,
          icon: a.icon,
          description: a.description,
          enabled: s.enabled !== false,
        };
      });
    }));
  }

  // ─── Active mode state ────────────────────────────────────────────
  // _currentMode: "ask_eli" (default Q&A) OR "agent:<agentId>".
  // Used by intercept_submit to decide whether to take over a Send
  // click in ask_eli, and by the dropdown UI to show the active row.
  // Resets to "ask_eli" on overlay close (per Phase 1 spec).
  var _currentMode = "ask_eli";
  function _setMode(mode) {
    _currentMode = mode;
    _onModeChange(mode);
  }
  function _onModeChange(mode) {
    // Update Send button labels in any mounted ask_eli inputs.
    document.querySelectorAll("[data-eli-agent-send-btn]").forEach(function (btn) {
      btn.textContent = (mode === "ask_eli") ? "Send" : "Plan Edits →";
    });
    // Update dropdown trigger label.
    document.querySelectorAll("[data-eli-agent-dropdown-label]").forEach(function (lbl) {
      var active = _currentDropdownLabel(mode);
      lbl.textContent = active.icon + " " + active.text;
    });
  }
  function _currentDropdownLabel(mode) {
    if (mode === "ask_eli") return { icon: "💬", text: "Ask Eli" };
    var agentId = mode.replace(/^agent:/, "");
    var a = _findAgent(agentId);
    return a ? { icon: a.icon, text: a.displayName } : { icon: "💬", text: "Ask Eli" };
  }

  // ─── Dropdown painter — listens for ask_eli's mount event ─────────
  // ask_eli emits 'ask_eli:input_mounted' after rendering its chat
  // input bar with { slotEl, sendBtn, inputEl, getQaContext }. We
  // paint the dropdown into slotEl, mark the send button so we can
  // flip its label on mode change, and rely on intercept_submit
  // (registered below) to take over when an agent mode is active.
  function _paintDropdown(payload) {
    var slot = payload && payload.slotEl;
    var sendBtn = payload && payload.sendBtn;
    if (!slot) return;
    if (sendBtn) sendBtn.setAttribute("data-eli-agent-send-btn", "1");

    var initialLabel = _currentDropdownLabel(_currentMode);
    slot.innerHTML =
      '<button type="button" class="_eg_dropdown_trigger" data-eli-agent-dropdown-trigger="1" ' +
      'title="Switch mode (Ask Eli vs an agent)">' +
        '<span data-eli-agent-dropdown-label="1">' + _esc(initialLabel.icon + " " + initialLabel.text) + '</span>' +
        '<span class="_eg_caret">▾</span>' +
      '</button>';

    var trigger = slot.querySelector('[data-eli-agent-dropdown-trigger="1"]');
    if (trigger) trigger.onclick = function (ev) {
      ev.preventDefault();
      ev.stopPropagation();
      _openDropdownMenu(trigger);
    };

    // Sync initial label state in case mode was set before mount.
    _onModeChange(_currentMode);
  }

  // Opens the floating menu anchored to the trigger button. List is
  // built fresh each open (so a Manage-Agents enable/disable change
  // takes effect without a full re-paint).
  function _openDropdownMenu(triggerEl) {
    _closeDropdownMenu();
    _listAgents().then(function (agents) {
      var rect = triggerEl.getBoundingClientRect();
      var menu = document.createElement("div");
      menu.id = "_eg_dropdown_menu";
      menu.style.cssText =
        "position:fixed;top:" + (rect.bottom + 4) + "px;left:" + rect.left + "px;" +
        "z-index:99999;background:#fff;border:1px solid #cbd5e1;" +
        "box-shadow:0 8px 24px rgba(15,23,42,0.18);min-width:240px;" +
        "font-family:Inter,'Segoe UI',system-ui,sans-serif;font-size:12px;";
      var rows = '';
      // Always-present Ask Eli row.
      rows += _menuRowHtml({ value: "ask_eli", icon: "💬", label: "Ask Eli", isActive: _currentMode === "ask_eli" });
      // Divider then enabled agents.
      var enabled = agents.filter(function (a) { return a.enabled; });
      if (enabled.length) rows += '<div class="_eg_menu_divider"></div>';
      enabled.forEach(function (a) {
        rows += _menuRowHtml({
          value: "agent:" + a.id, icon: a.icon, label: a.displayName,
          isActive: _currentMode === ("agent:" + a.id),
        });
      });
      // Footer — always-present Manage Agents action.
      rows += '<div class="_eg_menu_divider"></div>';
      rows += _menuRowHtml({ value: "__manage", icon: "⚙", label: "Manage Agents…", isActive: false, isAction: true });
      menu.innerHTML = rows;
      document.body.appendChild(menu);

      menu.querySelectorAll("[data-eg-menu-row]").forEach(function (row) {
        row.onclick = function () {
          var value = row.getAttribute("data-eg-menu-row");
          _closeDropdownMenu();
          if (value === "__manage") { _openManageAgentsModal(); return; }
          _setMode(value);
        };
      });
      // Outside-click closes menu.
      setTimeout(function () {
        document.addEventListener("mousedown", _outsideMenuClick, true);
      }, 0);
    });
  }
  function _menuRowHtml(opts) {
    var bg = opts.isActive ? "background:#dbeafe;color:#1e3a8a;" : "background:#fff;color:#0f172a;";
    return '<div data-eg-menu-row="' + _esc(opts.value) + '" class="_eg_menu_row' + (opts.isAction ? ' _eg_menu_row_action' : '') + '" ' +
      'style="display:flex;align-items:center;gap:8px;padding:8px 12px;cursor:pointer;' + bg + '">' +
        '<span style="font-size:13px;width:18px;text-align:center;">' + _esc(opts.icon) + '</span>' +
        '<span style="font-weight:' + (opts.isActive ? '700' : '500') + ';">' + _esc(opts.label) + '</span>' +
      '</div>';
  }
  function _closeDropdownMenu() {
    var existing = document.getElementById("_eg_dropdown_menu");
    if (existing && existing.parentNode) existing.parentNode.removeChild(existing);
    document.removeEventListener("mousedown", _outsideMenuClick, true);
  }
  function _outsideMenuClick(ev) {
    var menu = document.getElementById("_eg_dropdown_menu");
    if (!menu) return;
    if (menu.contains(ev.target)) return;
    // Don't close if the user clicked the trigger again — that's a
    // toggle which the trigger's own handler will manage.
    var trig = ev.target.closest && ev.target.closest("[data-eli-agent-dropdown-trigger]");
    if (trig) return;
    _closeDropdownMenu();
  }

  // ─── Agent overlay (Phase 1: empty shell echoing instruction) ─────
  // Phase 2/3 extend this with the planning pipeline + review cards.
  // For now: opens a draggable+resizable overlay showing the agent
  // name + the instruction the user typed in ask_eli, plus a status
  // line. Confirms end-to-end dispatch works.
  function _openAgentOverlay(payload) {
    _closeAgentOverlay();
    var agentId = payload && payload.agent;
    var instruction = (payload && payload.instruction) || "";
    var qaIndex = payload && payload.qaIndex;
    var docHash = payload && payload.docHash;
    var agent = _findAgent(agentId);
    if (!agent) {
      eli.log.event("tool", "eli_agent_open_unknown", { agent: agentId });
      return;
    }

    // Track active session state — Phase 2 will add plan, acceptance,
    // status, etc. Single session per doc per the locked spec.
    _egActive = {
      agent: agentId,
      instruction: instruction,
      qaIndex: qaIndex || null,
      docHash: docHash || null,
      plan: null,
      acceptance: {},
      status: "idle",
      openedAt: new Date().toISOString(),
    };

    var ov = document.createElement("div");
    ov.id = "_eli_agent_overlay";
    ov.className = "_eg_overlay";
    ov.innerHTML =
      '<div id="_eg_header" class="_eg_header">' +
        '<div class="_eg_header_title">' +
          '<span class="_eg_header_icon">' + _esc(agent.icon) + '</span>' +
          '<span class="_eg_header_label">' + _esc(agent.displayName) + '</span>' +
        '</div>' +
        '<div class="_eg_header_actions">' +
          '<button id="_eg_close" type="button" class="_eg_btn_ghost" title="Close">✕</button>' +
        '</div>' +
      '</div>' +
      '<div id="_eg_body" class="_eg_body">' +
        '<div class="_eg_section_label">INSTRUCTION</div>' +
        '<div class="_eg_instruction">' + _esc(instruction || "(no instruction provided)") + '</div>' +
        '<div class="_eg_section_label">CONTEXT</div>' +
        '<div class="_eg_context">' +
          '<div>QA index: ' + (qaIndex && qaIndex.length ? qaIndex.length + ' paragraphs' : 'not provided') + '</div>' +
          '<div>Doc hash: ' + _esc(docHash ? String(docHash).slice(0, 12) + '…' : 'not provided') + '</div>' +
        '</div>' +
        '<div class="_eg_status_box">' +
          '<div class="_eg_status_dot"></div>' +
          '<div>Phase 1 scaffold — planning + review pipeline lands in Phase 2/3.</div>' +
        '</div>' +
      '</div>';
    document.body.appendChild(ov);

    var headerEl = document.getElementById("_eg_header");
    if (typeof window._eliMakeDraggable === "function" && headerEl) {
      try { window._eliMakeDraggable(ov, headerEl); } catch (_) {}
    }
    if (typeof window._eliMakeResizable === "function") {
      try { window._eliMakeResizable(ov); } catch (_) {}
    }
    document.getElementById("_eg_close").onclick = _closeAgentOverlay;

    eli.log.event("tool", "eli_agent_overlay_opened", {
      agent: agentId,
      instructionLen: (instruction || "").length,
      hasQaIndex: !!qaIndex,
      hasDocHash: !!docHash,
    });
  }
  function _closeAgentOverlay() {
    var ov = document.getElementById("_eli_agent_overlay");
    if (ov && ov.parentNode) ov.parentNode.removeChild(ov);
    // Per Phase 1 spec: mode resets to Ask Eli on overlay close.
    if (_currentMode !== "ask_eli") _setMode("ask_eli");
  }
  // Active-session container — Phase 2 fills plan/acceptance, Phase 3
  // drives the review UI off it. Null when no overlay is open.
  var _egActive = null;

  // ─── Manage Agents modal ──────────────────────────────────────────
  // Barebones V1: list every registered agent with an enable toggle
  // and the agent's description. Tone/scope controls render but only
  // tone is editable in V1 (scope checkboxes ship in Phase 2 once the
  // planning prompt actually consumes them).
  function _openManageAgentsModal() {
    _closeManageAgentsModal();
    var modal = document.createElement("div");
    modal.id = "_eg_manage_modal";
    modal.className = "_eg_modal_backdrop";
    modal.innerHTML =
      '<div class="_eg_modal_panel">' +
        '<div class="_eg_modal_header">' +
          '<div class="_eg_modal_title">⚙ Manage Agents</div>' +
          '<button id="_eg_manage_close" type="button" class="_eg_btn_ghost">✕</button>' +
        '</div>' +
        '<div id="_eg_manage_body" class="_eg_modal_body">' +
          '<div style="font-size:11px;color:#64748b;text-align:center;padding:24px;">Loading agents…</div>' +
        '</div>' +
      '</div>';
    document.body.appendChild(modal);
    document.getElementById("_eg_manage_close").onclick = _closeManageAgentsModal;
    modal.onclick = function (ev) { if (ev.target === modal) _closeManageAgentsModal(); };
    _renderManageAgentsBody();
  }
  function _renderManageAgentsBody() {
    var body = document.getElementById("_eg_manage_body");
    if (!body) return;
    Promise.all(AGENT_REGISTRY.map(function (a) {
      return _getAgentSettings(a.id).then(function (s) { return { agent: a, settings: s }; });
    })).then(function (rows) {
      var html = '';
      rows.forEach(function (row) {
        var enabled = row.settings.enabled !== false;
        var tone = row.settings.tone || "balanced";
        html +=
          '<div class="_eg_manage_card">' +
            '<div class="_eg_manage_card_head">' +
              '<div class="_eg_manage_card_title">' +
                '<span style="font-size:18px;">' + _esc(row.agent.icon) + '</span>' +
                '<span>' + _esc(row.agent.displayName) + '</span>' +
              '</div>' +
              '<label class="_eg_toggle">' +
                '<input type="checkbox" data-eg-toggle-agent="' + _esc(row.agent.id) + '"' + (enabled ? ' checked' : '') + '>' +
                '<span>' + (enabled ? 'Enabled' : 'Disabled') + '</span>' +
              '</label>' +
            '</div>' +
            '<div class="_eg_manage_card_desc">' + _esc(row.agent.description) + '</div>' +
            '<div class="_eg_manage_card_settings">' +
              '<label class="_eg_setting_label">Default tone</label>' +
              '<select data-eg-tone="' + _esc(row.agent.id) + '">' +
                '<option value="conservative"' + (tone === "conservative" ? ' selected' : '') + '>Conservative</option>' +
                '<option value="balanced"' + (tone === "balanced" ? ' selected' : '') + '>Balanced</option>' +
                '<option value="aggressive"' + (tone === "aggressive" ? ' selected' : '') + '>Aggressive</option>' +
              '</select>' +
            '</div>' +
          '</div>';
      });
      body.innerHTML = html;
      _wireManageAgentsControls();
    }).catch(function (err) {
      body.innerHTML = '<div style="font-size:11px;color:#991b1b;padding:24px;text-align:center;">Failed to load agents: ' + _esc(err && err.message) + '</div>';
    });
  }
  function _wireManageAgentsControls() {
    document.querySelectorAll("[data-eg-toggle-agent]").forEach(function (cb) {
      cb.onchange = function () {
        var id = cb.getAttribute("data-eg-toggle-agent");
        _getAgentSettings(id).then(function (s) {
          s.enabled = cb.checked;
          return _setAgentSettings(id, s);
        }).then(function () {
          _renderManageAgentsBody();  // refresh enabled-state label
        });
      };
    });
    document.querySelectorAll("[data-eg-tone]").forEach(function (sel) {
      sel.onchange = function () {
        var id = sel.getAttribute("data-eg-tone");
        _getAgentSettings(id).then(function (s) {
          s.tone = sel.value;
          return _setAgentSettings(id, s);
        });
      };
    });
  }
  function _closeManageAgentsModal() {
    var modal = document.getElementById("_eg_manage_modal");
    if (modal && modal.parentNode) modal.parentNode.removeChild(modal);
  }

  // ─── Bus listener: paint dropdown when ask_eli mounts its input ───
  // ask_eli emits 'ask_eli:input_mounted' (additive patch) with
  // { slotEl, sendBtn, inputEl, getQaContext }. We paint into slotEl
  // and mark the send button for label-flip. If ask_eli isn't
  // patched yet (older bundle), this listener simply never fires.
  // Bundle CSS is auto-injected by the kernel from style.css — no
  // manual injection needed.
  if (eli.bus && typeof eli.bus.on === "function") {
    eli.bus.on("ask_eli:input_mounted", function (payload) {
      _paintDropdown(payload);
    });
  }

  // ─── Dispatch handlers ────────────────────────────────────────────
  // intercept_submit: ask_eli calls this BEFORE running its Q&A
  // pipeline. If the current mode isn't "ask_eli", we open the agent
  // overlay and return { handled: true } to short-circuit ask_eli's
  // Q&A path. Returning falsy lets Q&A proceed normally.
  eli.register({
    eli_agent: {
      list_agents: function () { return _listAgents(); },
      get_agent_settings: function (agentId) { return _getAgentSettings(agentId); },
      set_agent_settings: function (payload) {
        if (!payload || !payload.agentId) return Promise.reject(new Error("Missing agentId"));
        return _setAgentSettings(payload.agentId, payload.settings || {});
      },
      intercept_submit: function (payload) {
        if (!_currentMode || _currentMode === "ask_eli") return { handled: false };
        var agentId = _currentMode.replace(/^agent:/, "");
        _openAgentOverlay({
          agent: agentId,
          instruction: (payload && payload.instruction) || "",
          qaIndex: payload && payload.qaIndex,
          docHash: payload && payload.docHash,
        });
        return { handled: true };
      },
      open_agent: function (payload) { _openAgentOverlay(payload || {}); },
      get_current_mode: function () { return _currentMode; },
      set_mode: function (mode) { _setMode(mode); },
    },
    // Tile dispatch for users who pin the Manage Agents UI as a
    // standalone tile (audience controls keep this admin-only).
    tile: {
      app_eli_agent: function () { _openManageAgentsModal(); },
    },
  });

  // ─── Helpers ──────────────────────────────────────────────────────
  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }

  eli.log.event("tool", "eli_agent_initialized", { agentCount: AGENT_REGISTRY.length });
}

